// drives the status row's elapsed seconds, and no test can end with a
// pending timer.
library;

import 'dart:math';

import 'package:fa_ui/fa_ui.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart'
    show
