    final service = _PhaseService();
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(body: FaRunStatusRow(service: service)),
      ),
    );
    expect(find.byType(KaomojiFaceText), findsNothing);
    await tester.pumpWidget(const SizedBox.shrink());
