    await tester.pump(const Duration(seconds: 3));
    expect(
      tester.widget<Text>(find.byType(Text)).data,
      frozen,
      reason: 'an inactive indicator never animates',
    );
    await tester.pumpWidget(const SizedBox.shrink());
  });

