    final service = _PhaseService()
      ..rows.add(FaChatMessage(role: 'user', content: 'go'))
      ..streaming = true
      ..notify();
    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(body: FaRunStatusRow(service: service)),
      ),
    );
    expect(find.textContaining('Thinking'), findsOneWidget);

