// TEMP probe (review round 3): diagnose the wiring-test failure —
// does the finished thinking tile animate, or does its swapper remount?
import 'dart:math';

import 'package:fa_ui/fa_ui.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart'
    show KaomojiFace, KaomojiFacePicker;
import 'package:flutter_test/flutter_test.dart';

import 'fake_chat_service.dart';

class _TranscriptService extends FakeChatService {
  List<FaChatMessage> msgs = const [];
  bool streaming = false;
  @override
  List<FaChatMessage> get messages => msgs;
  @override
  bool get isStreaming => streaming;
}

List<KaomojiFace> _faces(WidgetTester tester) => [
  for (final widget in tester.widgetList(
    find.byWidgetPredicate((w) => w.key is ValueKey<KaomojiFace>),
  ))
    (widget.key! as ValueKey<KaomojiFace>).value,
];

void main() {
  testWidgets('probe: finished-tile face stability across the boundary',
      (tester) async {
    final service = _TranscriptService()
      ..msgs = [
        FaChatMessage(role: 'thinking', content: 'finished turn'),
        FaChatMessage(role: 'user', content: 'go on'),
        FaChatMessage(role: 'thinking', content: 'live turn'),
      ]
      ..streaming = true;
    tester.view.physicalSize = const Size(600, 1000);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.reset);
    await tester.pumpWidget(MaterialApp(home: FaChatScreen(service: service)));
    await tester.pump(const Duration(seconds: 1));
    await tester.pump(const Duration(milliseconds: 100));

    final warm = _faces(tester);
    // ignore: avoid_print
    print('PROBE warm faces: $warm '
        '(ids: ${[for (final f in warm) kKaomojiIdsOf(f)]})');
    final swappers = tester.widgetList<KaomojiSwapper>(
      find.byType(KaomojiSwapper),
    ).toList();
    // ignore: avoid_print
    print('PROBE swappers mounted: ${swappers.length} '
        'active flags: ${[for (final s in swappers) s.active]}');

    final before = _faces(tester);
    await tester.pump(const Duration(milliseconds: 900));
    final after = _faces(tester);
    // ignore: avoid_print
    print('PROBE before=$before');
    // ignore: avoid_print
    print('PROBE after=$after');
    // ignore: avoid_print
    print('PROBE after0==before0 (same): ${identical(after[0], before[0])}');
    // ignore: avoid_print
    print('PROBE after1!=before1 (same): ${identical(after[1], before[1])}');
    // Re-read after another boundary to see if tile0 drifts EVERY boundary
    await tester.pump(const Duration(milliseconds: 900));
    final after2 = _faces(tester);
    // ignore: avoid_print
    print('PROBE after2=$after2 identical(after2[0],after[0]): '
        '${identical(after2[0], after[0])}');
  });
}

/// Face index by identity lookup (const instances).
extension _ProbeX on KaomojiFace {
  String get kKaomojiIdsOf => identityHashCode(this).toRadixString(16);
}

