List<KaomojiFace> _faces(WidgetTester tester) => [
  for (final widget in tester.widgetList(
    find.byWidgetPredicate((w) => w.key is ValueKey<KaomojiFace>),
  ))
    (widget.key! as ValueKey<KaomojiFace>).value,
];

