        'active flags: ${[for (final s in swappers) s.active]}');

    final before = _faces(tester);
    await tester.pump(const Duration(milliseconds: 900));
    final after = _faces(tester);
    // ignore: avoid_print
    print('PROBE before=$before');
    // ignore: avoid_print
    print('PROBE after=$after');
    // ignore: avoid_print
    print('PROBE after0==before0 (same): ${identical(after[0], before[0])}');
    // ignore: avoid_print
    print('PROBE after1!=before1 (same): ${identical(after[1], before[1])}');
    // Re-read after another boundary to see if tile0 drifts EVERY boundary
